	'messages:apihelp-purge-example-generator' => 'en:Purge the first 10 pages in the main namespace.',
	'messages:apihelp-query-summary' => 'en:Fetch data from and about MediaWiki.',
	'messages:apihelp-query-extended-description' => 'en:All data modifications will first have to use query to acquire a token to prevent abuse from malicious sites.',
	'messages:apihelp-query-param-prop' => 'en:Which properties to get for the queried pages.',
	'messages:apihelp-query-param-list' => 'en:Which lists to get.',
	'messages:apihelp-query-param-meta' => 'en:Which metadata to get.',
